import { useEffect, useMemo, useRef, useState } from 'react';
import {
  crisp,
  dashedLine,
  makeScale,
  niceTicks,
  prepareCanvas,
  readTokens,
} from '../../canvas';
import {
  formatAxisTime,
  formatCompact,
  formatPercent,
  formatPrice,
  formatTime,
} from '../../format';
import { useElementSize } from '../../hooks';
import { useInstrument } from '../../theme/theme-provider';
import type { Candle, Instrument } from '../../types';
import { cn } from '../../utils';

export type CandleChartKind = 'candle' | 'hollow' | 'line' | 'area';

export interface MovingAverage {
  /** Lookback in bars. */
  period: number;
  /** Any CSS color, or a token like `var(--primary)`. */
  color?: string;
}

export interface CandleChartProps {
  candles: Candle[];
  instrument?: Partial<Instrument>;
  kind?: CandleChartKind;
  /** Fixed height in px. Omit to fill the parent, which must have a height. */
  height?: number;
  /** Volume histogram pinned to the bottom of the plot. */
  showVolume?: boolean;
  /** Dashed rule and axis tag at the latest close. */
  showLastPrice?: boolean;
  showGrid?: boolean;
  /** Crosshair plus an OHLC readout on hover. */
  crosshair?: boolean;
  /** Simple moving averages drawn over the series. */
  movingAverages?: MovingAverage[];
  /** Fires with the hovered bar, or null on leave - for syncing sibling panes. */
  onHoverCandle?: (candle: Candle | null, index: number) => void;
  className?: string;
}

const TOKENS = [
  '--up',
  '--down',
  '--up-line',
  '--down-line',
  '--chart-grid',
  '--chart-axis',
  '--chart-crosshair',
  '--card',
  '--muted',
  '--muted-foreground',
  '--foreground',
  '--primary',
  '--up-foreground',
  '--down-foreground',
] as const;

/**
 * Overlay colors are deliberately off the direction axis - violet, teal,
 * pink. Anything green, red, blue or amber would collide with `--up` / `--down`
 * in one of the two palettes, and an indicator line that looks like a
 * direction signal is worse than no indicator at all.
 */
const MA_FALLBACK = ['#8b5cf6', '#14b8a6', '#ec4899'];
const AXIS_WIDTH = 58;
const TIME_AXIS_HEIGHT = 20;
const PAD = 8;

/** Simple moving average, `null` until the window is full. */
function sma(values: number[], period: number): Array<number | null> {
  const out: Array<number | null> = new Array(values.length).fill(null);
  let sum = 0;
  for (let i = 0; i < values.length; i++) {
    sum += values[i];
    if (i >= period) sum -= values[i - period];
    if (i >= period - 1) out[i] = sum / period;
  }
  return out;
}

/**
 * OHLC chart on a 2D canvas.
 *
 * Canvas, not SVG: a 240-bar candle chart is roughly a thousand DOM nodes as
 * SVG and re-layouts that whole subtree on every tick, while one canvas
 * repaint costs about the same whether it draws 50 bars or 5,000. The trade-off
 * is that canvas cannot inherit `var(--up)`, so the chart resolves its tokens
 * from the live computed style on each draw and stays theme-accurate anyway.
 */
export function CandleChart({
  candles,
  instrument,
  kind = 'candle',
  height,
  showVolume = true,
  showLastPrice = true,
  showGrid = true,
  crosshair = true,
  movingAverages,
  onHoverCandle,
  className,
}: CandleChartProps) {
  const inst = useInstrument(instrument);
  const [wrapRef, size] = useElementSize<HTMLDivElement>();
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [hover, setHover] = useState<{ index: number; x: number; y: number } | null>(null);

  const width = size.width;
  const chartHeight = height ?? size.height;

  const averages = useMemo(() => {
    if (!movingAverages?.length) return [];
    const closes = candles.map((c) => c.close);
    return movingAverages.map((ma, i) => ({
      ...ma,
      color: ma.color ?? MA_FALLBACK[i % MA_FALLBACK.length],
      values: sma(closes, ma.period),
    }));
  }, [candles, movingAverages]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap || width < 2 || chartHeight < 2 || candles.length === 0) return;

    const ctx = prepareCanvas(canvas, width, chartHeight);
    if (!ctx) return;
    const c = readTokens(wrap, TOKENS);

    const plotLeft = PAD;
    const plotRight = width - AXIS_WIDTH;
    const plotWidth = Math.max(1, plotRight - plotLeft);
    const plotTop = PAD;
    const plotBottom = chartHeight - TIME_AXIS_HEIGHT;
    const volumeHeight = showVolume ? Math.max(24, (plotBottom - plotTop) * 0.18) : 0;
    const priceBottom = plotBottom - (volumeHeight ? volumeHeight + 6 : 0);

    let lo = Infinity;
    let hi = -Infinity;
    for (const bar of candles) {
      if (bar.low < lo) lo = bar.low;
      if (bar.high > hi) hi = bar.high;
    }
    for (const ma of averages) {
      for (const v of ma.values) {
        if (v === null) continue;
        if (v < lo) lo = v;
        if (v > hi) hi = v;
      }
    }
    // 4% headroom top and bottom so wicks never touch the frame.
    const pad = (hi - lo) * 0.04 || hi * 0.004 || 1;
    const y = makeScale(lo - pad, hi + pad, priceBottom, plotTop);

    const slot = plotWidth / candles.length;
    const bodyWidth = Math.max(1, Math.min(14, slot * 0.68));
    const xOf = (i: number) => plotLeft + slot * (i + 0.5);

    ctx.font = '10px ui-monospace, monospace';
    ctx.textBaseline = 'middle';

    // --- grid + price axis ---
    const lastBar = candles[candles.length - 1];
    const lastY = y(lastBar.close);
    const ticks = niceTicks(
      lo - pad,
      hi + pad,
      Math.max(2, Math.floor((priceBottom - plotTop) / 46)),
    );
    for (const tick of ticks) {
      const ty = y(tick);
      if (ty < plotTop - 1 || ty > priceBottom + 1) continue;
      if (showGrid) {
        ctx.strokeStyle = c['--chart-grid'];
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(plotLeft, crisp(ty));
        ctx.lineTo(plotRight, crisp(ty));
        ctx.stroke();
      }
      // The last-price tag is painted over this axis later; drop any label it
      // would land on rather than stacking two numbers in the same place.
      if (showLastPrice && Math.abs(ty - lastY) < 11) continue;
      ctx.fillStyle = c['--chart-axis'];
      ctx.textAlign = 'left';
      ctx.fillText(formatPrice(tick, inst.pricePrecision), plotRight + 6, ty);
    }

    // --- time axis ---
    const labelEvery = Math.max(1, Math.ceil(candles.length / Math.max(1, Math.floor(plotWidth / 64))));
    ctx.textAlign = 'center';
    ctx.fillStyle = c['--chart-axis'];
    for (let i = candles.length - 1; i >= 0; i -= labelEvery) {
      const bar = candles[i];
      const prev = candles[i - labelEvery];
      const newDay = prev ? new Date(prev.time).getDate() !== new Date(bar.time).getDate() : false;
      ctx.fillText(formatAxisTime(bar.time, newDay), xOf(i), plotBottom + TIME_AXIS_HEIGHT / 2);
    }
    ctx.strokeStyle = c['--chart-grid'];
    ctx.beginPath();
    ctx.moveTo(plotLeft, crisp(plotBottom));
    ctx.lineTo(plotRight, crisp(plotBottom));
    ctx.stroke();

    // --- volume ---
    if (volumeHeight > 0) {
      let maxVolume = 0;
      for (const bar of candles) if (bar.volume > maxVolume) maxVolume = bar.volume;
      for (let i = 0; i < candles.length; i++) {
        const bar = candles[i];
        const h = maxVolume ? (bar.volume / maxVolume) * volumeHeight : 0;
        ctx.fillStyle = bar.close >= bar.open ? c['--up-line'] : c['--down-line'];
        ctx.globalAlpha = 0.5;
        ctx.fillRect(xOf(i) - bodyWidth / 2, plotBottom - h, bodyWidth, h);
      }
      ctx.globalAlpha = 1;
    }

    // --- price series ---
    const tracePath = () => {
      ctx.beginPath();
      for (let i = 0; i < candles.length; i++) {
        const px = xOf(i);
        const py = y(candles[i].close);
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
    };

    if (kind === 'candle' || kind === 'hollow') {
      for (let i = 0; i < candles.length; i++) {
        const bar = candles[i];
        const up = bar.close >= bar.open;
        const color = up ? c['--up'] : c['--down'];
        const cx = xOf(i);

        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(crisp(cx), y(bar.high));
        ctx.lineTo(crisp(cx), y(bar.low));
        ctx.stroke();

        const openY = y(bar.open);
        const closeY = y(bar.close);
        const top = Math.min(openY, closeY);
        // A doji still needs a visible 1px body.
        const bodyHeight = Math.max(1, Math.abs(closeY - openY));

        if (kind === 'hollow' && up) {
          ctx.strokeRect(
            crisp(cx - bodyWidth / 2),
            crisp(top),
            Math.round(bodyWidth),
            Math.round(bodyHeight),
          );
        } else {
          ctx.fillStyle = color;
          ctx.fillRect(cx - bodyWidth / 2, top, bodyWidth, bodyHeight);
        }
      }
    } else {
      const up = lastBar.close >= candles[0].open;
      const line = up ? c['--up'] : c['--down'];

      if (kind === 'area') {
        const gradient = ctx.createLinearGradient(0, plotTop, 0, priceBottom);
        gradient.addColorStop(0, up ? c['--up-line'] : c['--down-line']);
        gradient.addColorStop(1, 'transparent');
        ctx.save();
        tracePath();
        ctx.lineTo(xOf(candles.length - 1), priceBottom);
        ctx.lineTo(xOf(0), priceBottom);
        ctx.closePath();
        ctx.globalAlpha = 0.7;
        ctx.fillStyle = gradient;
        ctx.fill();
        ctx.restore();
      }

      // Re-trace: an area fill closes the path back along the baseline, which
      // would otherwise be stroked as part of the line.
      tracePath();
      ctx.strokeStyle = line;
      ctx.lineWidth = 1.5;
      ctx.lineJoin = 'round';
      ctx.stroke();
    }

    // --- moving averages ---
    for (const ma of averages) {
      ctx.beginPath();
      let started = false;
      for (let i = 0; i < ma.values.length; i++) {
        const v = ma.values[i];
        if (v === null) continue;
        const px = xOf(i);
        const py = y(v);
        if (!started) {
          ctx.moveTo(px, py);
          started = true;
        } else {
          ctx.lineTo(px, py);
        }
      }
      if (!started) continue;
      ctx.strokeStyle = ma.color.startsWith('var(')
        ? readTokens(wrap, [ma.color.slice(4, -1) as '--primary'])[
            ma.color.slice(4, -1) as '--primary'
          ]
        : ma.color;
      ctx.lineWidth = 1.25;
      ctx.lineJoin = 'round';
      ctx.stroke();
    }

    // --- last price ---
    if (showLastPrice) {
      const prior = candles.length > 1 ? candles[candles.length - 2].close : lastBar.open;
      const up = lastBar.close >= prior;
      ctx.strokeStyle = up ? c['--up'] : c['--down'];
      ctx.lineWidth = 1;
      dashedLine(ctx, plotLeft, crisp(lastY), plotRight, crisp(lastY), [4, 4]);

      ctx.fillStyle = up ? c['--up'] : c['--down'];
      ctx.fillRect(plotRight + 2, lastY - 8, AXIS_WIDTH - 4, 16);
      ctx.fillStyle = up ? c['--up-foreground'] : c['--down-foreground'];
      ctx.textAlign = 'center';
      ctx.fillText(
        formatPrice(lastBar.close, inst.pricePrecision),
        plotRight + 2 + (AXIS_WIDTH - 4) / 2,
        lastY,
      );
    }

    // --- crosshair ---
    if (crosshair && hover && candles[hover.index]) {
      const cx = xOf(hover.index);
      ctx.strokeStyle = c['--chart-crosshair'];
      ctx.lineWidth = 1;
      dashedLine(ctx, crisp(cx), plotTop, crisp(cx), plotBottom, [3, 3]);
      const hy = Math.min(Math.max(hover.y, plotTop), priceBottom);
      dashedLine(ctx, plotLeft, crisp(hy), plotRight, crisp(hy), [3, 3]);

      ctx.fillStyle = c['--muted'];
      ctx.fillRect(plotRight + 2, hy - 8, AXIS_WIDTH - 4, 16);
      ctx.fillStyle = c['--muted-foreground'];
      ctx.textAlign = 'center';
      ctx.fillText(
        formatPrice(y.invert(hy), inst.pricePrecision),
        plotRight + 2 + (AXIS_WIDTH - 4) / 2,
        hy,
      );
    }
  }, [
    candles,
    averages,
    width,
    chartHeight,
    kind,
    showVolume,
    showLastPrice,
    showGrid,
    crosshair,
    hover,
    inst.pricePrecision,
    wrapRef,
  ]);

  const hovered = hover ? candles[hover.index] : undefined;

  const handleMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (!crosshair || candles.length === 0) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const plotWidth = Math.max(1, rect.width - AXIS_WIDTH - PAD);
    const slot = plotWidth / candles.length;
    const index = Math.min(candles.length - 1, Math.max(0, Math.floor((x - PAD) / slot)));
    setHover({ index, x, y: e.clientY - rect.top });
    onHoverCandle?.(candles[index] ?? null, index);
  };

  const clearHover = () => {
    setHover(null);
    onHoverCandle?.(null, -1);
  };

  // The readout flips to the left of the cursor near the right edge so it is
  // never clipped by the panel.
  const flip = hover ? hover.x > width - 170 : false;

  return (
    <div
      ref={wrapRef}
      className={cn('relative min-h-0 w-full', className)}
      style={{ height: height ?? '100%' }}
      onPointerMove={handleMove}
      onPointerLeave={clearHover}
    >
      <canvas ref={canvasRef} className="block size-full" />
      {hovered && hover && (
        <div
          className="bg-popover text-popover-foreground pointer-events-none absolute z-20 flex flex-col gap-0.5 rounded-md border p-2 font-mono text-[10px] tabular-nums shadow-lg"
          style={{
            left: flip ? undefined : hover.x + 12,
            right: flip ? width - hover.x + 12 : undefined,
            top: Math.min(hover.y + 12, Math.max(0, chartHeight - 96)),
          }}
        >
          <div className="flex justify-between gap-4">
            <span className="text-muted-foreground">{formatTime(hovered.time).slice(0, 5)}</span>
            <span
              className={cn('font-semibold', hovered.close >= hovered.open ? 'text-up' : 'text-down')}
            >
              {formatPercent((hovered.close - hovered.open) / hovered.open)}
            </span>
          </div>
          {(['open', 'high', 'low', 'close'] as const).map((key) => (
            <div className="flex justify-between gap-4" key={key}>
              <span className="text-muted-foreground">{key[0].toUpperCase()}</span>
              <span className="font-semibold">
                {formatPrice(hovered[key], inst.pricePrecision)}
              </span>
            </div>
          ))}
          <div className="flex justify-between gap-4">
            <span className="text-muted-foreground">Vol</span>
            <span className="font-semibold">{formatCompact(hovered.volume)}</span>
          </div>
        </div>
      )}
    </div>
  );
}

/** Canvas plumbing shared by the chart components. */

export interface ChartPadding {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/**
 * Sizes the backing store to the device pixel ratio and returns a context
 * already scaled to CSS pixels, so drawing code can use layout units and still
 * get crisp 1px gridlines on a HiDPI screen.
 */
export function prepareCanvas(
  canvas: HTMLCanvasElement,
  width: number,
  height: number,
): CanvasRenderingContext2D | null {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = Math.max(1, Math.floor(width * dpr));
  const h = Math.max(1, Math.floor(height * dpr));
  if (canvas.width !== w) canvas.width = w;
  if (canvas.height !== h) canvas.height = h;

  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  return ctx;
}

/**
 * Resolves CSS custom properties against a live element. The charts paint on
 * canvas, which cannot inherit `var(--tu-up)`, so they read the tokens once
 * per draw and stay in sync with whatever theme the host applied.
 */
export function readTokens<K extends string>(
  el: Element,
  names: readonly K[],
): Record<K, string> {
  const style = getComputedStyle(el);
  const out = {} as Record<K, string>;
  for (const name of names) {
    out[name] = style.getPropertyValue(name).trim() || '#888';
  }
  return out;
}

/** Linear scale from a data domain to a pixel range. */
export function makeScale(
  domainMin: number,
  domainMax: number,
  rangeMin: number,
  rangeMax: number,
) {
  const span = domainMax - domainMin || 1;
  const pixels = rangeMax - rangeMin;
  const scale = (value: number) => rangeMin + ((value - domainMin) / span) * pixels;
  scale.invert = (pixel: number) => domainMin + ((pixel - rangeMin) / pixels) * span;
  return scale;
}

/**
 * "Nice" tick values at human-readable intervals (1, 2, 5 x 10^n) so the price
 * axis reads 42.50 / 43.00 / 43.50 instead of 42.37 / 42.91 / 43.45.
 */
export function niceTicks(min: number, max: number, target = 5): number[] {
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) return [min];
  const raw = (max - min) / target;
  const magnitude = Math.pow(10, Math.floor(Math.log10(raw)));
  const normalized = raw / magnitude;
  const step =
    (normalized >= 5 ? 10 : normalized >= 2 ? 5 : normalized >= 1 ? 2 : 1) * magnitude;

  const ticks: number[] = [];
  for (let t = Math.ceil(min / step) * step; t <= max + step * 1e-6; t += step) {
    ticks.push(Number(t.toFixed(10)));
  }
  return ticks;
}

/** Snaps a coordinate to a half-pixel so a 1px stroke lands on one pixel row. */
export function crisp(value: number): number {
  return Math.round(value) + 0.5;
}

/** Fills a rounded rect; `ctx.roundRect` is still patchy in older Safari. */
export function fillRoundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
) {
  const radius = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + w - radius, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
  ctx.lineTo(x + w, y + h - radius);
  ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  ctx.lineTo(x + radius, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.fill();
}

/** Dashed horizontal rule used for the last-price and crosshair lines. */
export function dashedLine(
  ctx: CanvasRenderingContext2D,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  dash: number[] = [3, 3],
) {
  ctx.save();
  ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  ctx.restore();
}

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
